const https = require('https');

// Flowise automatically provides your tool inputs as variables prefixed with a $
const alertData = JSON.stringify({
    event: $event,
    severity: $severity,
    details: $details,
    timestamp: new Date().toISOString()
});

// REPLACE https://example.com WITH YOUR WEBHOOK.SITE URL TO SEE IT LIVE
const destinationUrl = 'https://example.com'; 

const options = {
    hostname: 'qstash-eu-central-1.upstash.io',
    port: 443,
    path: '/v2/publish/' + destinationUrl, 
    method: 'POST',
    headers: {
        'Authorization': 'Bearer eyJVc2VySUQiOiIzNjVhNzUyMi04NmExLTQ0MDktYmZlMC01ZjgzNDI3M2RlNDciLCJQYXNzd29yZCI6ImQzMDA4NjUyZTgzMDRmYzBhNDYwNGJmMGY5NGEzNGUwIn0=',
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(alertData)
    }
};

// We execute the Promise and return it directly so the AI gets the final result
return await new Promise((resolve) => {
    const req = https.request(options, (res) => {
        let body = '';
        res.on('data', c => body += c);
        res.on('end', () => {
            // This returns a readable string back to the Agent
            resolve(JSON.stringify({ 
                status: res.statusCode >= 200 && res.statusCode < 300 ? "Success" : "Failed", 
                status_code: res.statusCode, 
                details: body 
            }));
        });
    });

    req.on('error', e => resolve(JSON.stringify({ status: "Error", msg: e.message })));
    req.write(alertData);
    req.end();
});
